questionvariables.text:
stack_include("contribl://prooflib.mac");
proof_steps: [
 ["intro", "Let \\(r\\) be a rational number. Then \\(r = \\dfrac{a}{b}\\) for some integers \\(a\\) and \\(b\\) with \\(b \\neq 0\\)."],
 ["split", "Then \\(r = (r - \\sqrt{2}) + \\sqrt{2}\\)."],
 ["known", "We know that \\(\\sqrt{2}\\) is irrational."],
 ["assume", "Suppose, for contradiction, that \\(r - \\sqrt{2}\\) is rational. Then \\(r - \\sqrt{2} = \\dfrac{c}{d}\\) for some integers \\(c\\) and \\(d\\) with \\(d \\neq 0\\)."],
 ["derive", "So \\(\\sqrt{2} = r - \\dfrac{c}{d} = \\dfrac{a}{b} - \\dfrac{c}{d} = \\dfrac{ad - bc}{bd}\\)."],
 ["contra", "Since \\(ad - bc\\) and \\(bd\\) are integers and \\(bd \\neq 0\\), \\(\\sqrt{2}\\) is rational. This is a contradiction, so \\(r - \\sqrt{2}\\) is irrational."],
 ["conc", "So \\(r = (r - \\sqrt{2}) + \\sqrt{2}\\) is the sum of the two irrational numbers \\(r - \\sqrt{2}\\) and \\(\\sqrt{2}\\)."],
 ["d_irr", "Suppose, for contradiction, that \\(r - \\sqrt{2}\\) is irrational."],
 ["d_all", "Suppose, for contradiction, that every rational number is the sum of two irrational numbers."],
 ["d_eg", "For example, \\(1 = (1 - \\sqrt{2}) + \\sqrt{2}\\) and \\(2 = (2 - \\sqrt{2}) + \\sqrt{2}\\). So every rational number is the sum of two irrational numbers."]
];
proof_steps: random_permutation(proof_steps);
/* Dependency graph: each path is a chain of steps that must come in this order.
   known may come anywhere before contra; split anywhere after intro and before conc;
   the inner proof before or after split. d_irr, d_all and d_eg are logically wrong blocks in no path. */
tdag: [["intro", "assume", "derive", "contra", "conc"], ["known", "contra"], ["intro", "split", "conc"]];
ta: proof("intro", "split", "known", "assume", "derive", "contra", "conc");

feedbackvariables.text:
sa: parsons_decode(ans1);
saprob: proof_assessment_dag(sa, tdag);
usedkeys: args(sa);
usedirr: member("d_irr", usedkeys);
usedall: member("d_all", usedkeys);
usedeg: member("d_eg", usedkeys);
usedwrong: usedirr or usedall or usedeg;
missk: listify(apply(union, cons({}, map(lambda([ex], first(args(ex))), sublist(saprob, lambda([ex], safe_op(ex) = "proof_step_missing"))))));
mustp: map(args, sublist(saprob, lambda([ex], safe_op(ex) = "proof_step_must")));
